@Component("consent-handler")
@ProcessingGroup("consent-processing-group")
public class ConsentEventHandler {
	
	// core constructor
	ConsentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateConsentEvent
     */
    @EventHandler
    public void handle( CreateConsentEvent event) {
        entityManager.persist(new Consent(event.getConsentId(), event.getGrantedAt(), event.getExpiresAt(), event.getScope(), event.getCustomer(), event.getApiClient(), event.getConsentType(), event.getStatus()));
    }

    /*
     * @param	event UpdateConsentEvent
     */
    @EventHandler
    public Consent handle( UpdateConsentEvent event) {
    	entityManager.merge(new Consent(event.getConsentId(), event.getGrantedAt(), event.getExpiresAt(), event.getScope(), event.getCustomer(), event.getApiClient(), event.getConsentType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteConsentEvent
     */
    @EventHandler
    public void on( DeleteConsentEvent event) {
    	Consent entity = new Consent();
   
    	// ------------------------------------------
    	// apply the ConsentId
    	// ------------------------------------------
    	entity.setConsentId( event.getConsentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ConsentRepository consentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ConsentEventHandler.class.getName());

}
